using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogs) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogs)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [FormerlySerializedAs("debugLogs")]
    [SerializeField] private bool debugLogsDirectional = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogsDirectional) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogsDirectional)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using BridgeItTogether.Gameplay.Abstractions;

public class Catapult : MonoBehaviour, IInteractable
{
    // Evento estático para notificar cuando cualquier catapulta es usada
    public static event System.Action<Catapult> OnCatapultUsed;

    [Header("Launch Settings")]
    [SerializeField] private Transform launchPoint;
    [SerializeField] private Transform targetPoint;
    [SerializeField, Range(10f, 80f)] private float launchAngleDeg = 45f;
    [SerializeField, Min(0.1f)] private float launchSpeed = 12f;
    [SerializeField, Min(0.1f)] private float launchGravity = 9.81f;
    [SerializeField] private bool kinematicDuringLaunch = true;
    [SerializeField] private float minLaunchDistance = 0.05f;

    [Header("Catapult Rotation")]
    [SerializeField] private Transform rotatingArm;
    [SerializeField] private Transform launchSocket;
    [SerializeField] private float lowAngle = -90f;
    [SerializeField] private float highAngle = 180f;
    [SerializeField] private float launchRotationSpeed = 90f;
    [SerializeField] private float reloadRotationSpeed = 45f;

    [Header("Interaction")]
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;

    private readonly Dictionary<Transform, Coroutine> activeLaunches = new();

    [SerializeField] private bool isReady = true;
    private GameObject loadedObject;
    private Coroutine currentOperation;

    public InteractPriority InteractPriority => interactPriority;

    public void Interact(GameObject interactor)
    {
        if (!isReady || !targetPoint) return;

        var playerHolder = interactor.GetComponent<PlayerObjectHolder>();
        if (!playerHolder || !playerHolder.HasObjectInHand()) return;

        GameObject objectInHand = playerHolder.GetHeldObject();
        if (!IsValidHandObject(objectInHand)) return;

        loadedObject = objectInHand;
        var objTransform = objectInHand.transform;

        ClearPlayerHolder(playerHolder);

        Transform parentSocket = launchSocket ? launchSocket : rotatingArm;
        objTransform.SetParent(parentSocket, true);
        objTransform.localPosition = Vector3.zero;
        objTransform.localRotation = Quaternion.identity;

        isReady = false;
        if (currentOperation != null)
            StopCoroutine(currentOperation);
        currentOperation = StartCoroutine(LaunchSequence());

        // Notificar que la catapulta fue usada (para tutoriales)
        OnCatapultUsed?.Invoke(this);
    }

    private IEnumerator LaunchSequence()
    {
        yield return StartCoroutine(RotateToHighAngle());

        if (loadedObject && targetPoint)
        {
            var hitable = loadedObject.GetComponent<IHitable>();
            var targetT = loadedObject.transform;
            Vector3 destino = targetPoint.position;

            targetT.SetParent(null, true);
            hitable?.OnLaunched(destino);

            var routine = StartCoroutine(LaunchRoutine(targetT, destino));
            activeLaunches[targetT] = routine;

            loadedObject = null;
        }

        yield return StartCoroutine(RotateToLowAngle());

        isReady = true;
        currentOperation = null;
    }

    private void ClearPlayerHolder(PlayerObjectHolder holder)
    {
        var heldObjectField = typeof(PlayerObjectHolder).GetField("heldObject",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

        if (heldObjectField != null)
            heldObjectField.SetValue(holder, null);

        var disabledCollidersField = typeof(PlayerObjectHolder).GetField("heldDisabledColliders",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

        if (disabledCollidersField != null)
        {
            var list = disabledCollidersField.GetValue(holder) as System.Collections.IList;
            list?.Clear();
        }

        var rigidbodyField = typeof(PlayerObjectHolder).GetField("heldRigidbody",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

        if (rigidbodyField != null)
            rigidbodyField.SetValue(holder, null);
    }

    private bool IsValidHandObject(GameObject obj)
    {
        if (!obj) return false;

        if (obj.GetComponent<IHitable>() != null) return true;
        if (obj.GetComponent<PaloIgnifugo>() != null) return true;
        if (obj.GetComponent<MaterialTipo1>() != null) return true;
        //if (obj.CompareTag("Item") || obj.CompareTag("Projectile")) return true;

        return false;
    }

    private void Awake()
    {
        if (!launchPoint) launchPoint = transform;
        if (!rotatingArm) rotatingArm = transform;
        if (!launchSocket) launchSocket = rotatingArm;
    }

    private void OnValidate()
    {
        if (!launchPoint) launchPoint = transform;
        if (!rotatingArm) rotatingArm = transform;
        if (!launchSocket) launchSocket = rotatingArm;
    }

    private void Start()
    {
        if (rotatingArm)
        {
            rotatingArm.localRotation = Quaternion.Euler(0f, 0f, lowAngle);
        }
        isReady = true;
    }

    public void SetTargetPoint(Transform target)
    {
        targetPoint = target;
    }

    private IEnumerator RotateToHighAngle()
    {
        if (!rotatingArm) yield break;

        float startAngle = rotatingArm.localEulerAngles.z;
        float targetAngle = highAngle;

        // Normalizar ángulos al rango -180 a 180
        if (startAngle > 180f) startAngle -= 360f;
        if (targetAngle > 180f) targetAngle -= 360f;

        // Calcular la diferencia y elegir el camino más corto
        float diff = targetAngle - startAngle;
        if (diff > 180f) diff -= 360f;
        if (diff < -180f) diff += 360f;

        float actualTarget = startAngle + diff;

        float duration = Mathf.Abs(diff) / launchRotationSpeed;

        float t = 0f;
        while (t < duration)
        {
            t += Time.deltaTime;
            float progress = t / duration;
            float currentAngle = Mathf.Lerp(startAngle, actualTarget, progress);
            rotatingArm.localRotation = Quaternion.Euler(0f, 0f, currentAngle);
            yield return null;
        }

        rotatingArm.localRotation = Quaternion.Euler(0f, 0f, targetAngle);
    }

    private IEnumerator RotateToLowAngle()
    {
        if (!rotatingArm) yield break;

        float startAngle = rotatingArm.localEulerAngles.z;
        float targetAngle = lowAngle;

        // Normalizar ángulos al rango -180 a 180
        if (startAngle > 180f) startAngle -= 360f;
        if (targetAngle > 180f) targetAngle -= 360f;

        // Calcular la diferencia y elegir el camino más corto
        float diff = targetAngle - startAngle;
        if (diff > 180f) diff -= 360f;
        if (diff < -180f) diff += 360f;

        float actualTarget = startAngle + diff;

        float duration = Mathf.Abs(diff) / reloadRotationSpeed;

        float t = 0f;
        while (t < duration)
        {
            t += Time.deltaTime;
            float progress = t / duration;
            float currentAngle = Mathf.Lerp(startAngle, actualTarget, progress);
            rotatingArm.localRotation = Quaternion.Euler(0f, 0f, currentAngle);
            yield return null;
        }

        rotatingArm.localRotation = Quaternion.Euler(0f, 0f, targetAngle);
    }

    private IEnumerator LaunchRoutine(Transform target, Vector3 destino)
    {
        if (!target) yield break;

        Vector3 start = launchPoint ? launchPoint.position : target.position;
        Vector3 startXZ = new Vector3(start.x, 0f, start.z);
        Vector3 endXZ = new Vector3(destino.x, 0f, destino.z);
        Vector3 flat = endXZ - startXZ;
        float distance = flat.magnitude;

        if (distance < minLaunchDistance)
        {
            target.position = destino;
            activeLaunches.Remove(target);
            yield break;
        }

        Vector3 dir = flat / Mathf.Max(distance, 0.0001f);
        float angleRad = launchAngleDeg * Mathf.Deg2Rad;
        float v = Mathf.Max(0.01f, launchSpeed);
        float g = Mathf.Max(0.01f, launchGravity);
        float sinAngle = Mathf.Sin(angleRad);
        float cosAngle = Mathf.Cos(angleRad);

        float a = -0.5f * g;
        float b = v * sinAngle;
        float c = start.y - destino.y;

        float discriminant = b * b - 4f * a * c;
        float totalTime;

        if (discriminant >= 0f)
        {
            float t1 = (-b + Mathf.Sqrt(discriminant)) / (2f * a);
            float t2 = (-b - Mathf.Sqrt(discriminant)) / (2f * a);
            totalTime = Mathf.Max(t1, t2);
        }
        else
        {
            totalTime = distance / (v * cosAngle);
        }

        totalTime = Mathf.Max(0.5f, totalTime);

        Rigidbody trb = target.GetComponent<Rigidbody>();
        bool hadRB = trb != null;
        bool prevKinematic = false;
        if (hadRB && kinematicDuringLaunch)
        {
            prevKinematic = trb.isKinematic;
            trb.isKinematic = true;
        }

        float t = 0f;
        while (t < totalTime && target != null)
        {
            t += Time.deltaTime;
            float progress = Mathf.Min(t / totalTime, 1f);

            Vector3 horizontalPos = Vector3.Lerp(start, destino, progress);
            float currentHeight = start.y + (v * sinAngle * t) - (0.5f * g * t * t);
            Vector3 currentPos = new Vector3(horizontalPos.x, currentHeight, horizontalPos.z);
            target.position = currentPos;

            yield return null;
        }

        if (target != null)
            target.position = destino;

        if (hadRB && kinematicDuringLaunch && trb != null)
            trb.isKinematic = prevKinematic;

        if (target != null)
            activeLaunches.Remove(target);
    }

    public bool IsReady() => isReady;
    public bool HasLoadedObject() => loadedObject != null;

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        if (launchPoint && targetPoint)
        {
            Gizmos.color = Color.red;
            Gizmos.DrawLine(launchPoint.position, targetPoint.position);
            Gizmos.DrawWireSphere(targetPoint.position, 0.5f);
        }

        if (rotatingArm)
        {
            Gizmos.color = Color.blue;
            Gizmos.DrawWireSphere(rotatingArm.position, 0.2f);

            Vector3 lowDir = Quaternion.Euler(0f, 0f, lowAngle) * Vector3.right;
            Gizmos.DrawLine(rotatingArm.position, rotatingArm.position + lowDir * 1f);

            Gizmos.color = Color.cyan;
            Vector3 highDir = Quaternion.Euler(0f, 0f, highAngle) * Vector3.right;
            Gizmos.DrawLine(rotatingArm.position, rotatingArm.position + highDir * 1f);
        }

        if (launchSocket)
        {
            Gizmos.color = Color.yellow;
            Gizmos.DrawWireCube(launchSocket.position, Vector3.one * 0.2f);
        }
    }
#endif
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using BridgeItTogether.Gameplay.Abstractions;

public class Catapult : MonoBehaviour, IInteractable
{
    // Evento estático para notificar cuando cualquier catapulta es usada
    public static event System.Action<Catapult> OnCatapultUsed;

    [Header("Launch Settings")]
    [SerializeField] private Transform launchPoint;
    [SerializeField] private Transform targetPoint;
    [SerializeField, Range(10f, 80f)] private float launchAngleDeg = 45f;
    [SerializeField, Min(0.1f)] private float launchSpeed = 12f;
    [SerializeField, Min(0.1f)] private float launchGravity = 9.81f;
    [SerializeField] private bool kinematicDuringLaunch = true;
    [SerializeField] private float minLaunchDistance = 0.05f;

    [Header("Catapult Rotation")]
    [SerializeField] private Transform rotatingArm;
    [SerializeField] private Transform launchSocket;
    [SerializeField] private float lowAngle = -90f;
    [SerializeField] private float highAngle = 180f;
    [SerializeField] private float launchRotationSpeed = 90f;
    [SerializeField] private float reloadRotationSpeed = 45f;

    [Header("Interaction")]
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;

    [Header("UI")]
    [SerializeField] private Image reloadImage;

    private readonly Dictionary<Transform, Coroutine> activeLaunches = new();

    [SerializeField] private bool isReady = true;
    private GameObject loadedObject;
    private Coroutine currentOperation;
    private Coroutine reloadUIUpdateCoroutine;

    public InteractPriority InteractPriority => interactPriority;

    public void Interact(GameObject interactor)
    {
        if (!isReady || !targetPoint) return;

        var playerHolder = interactor.GetComponent<PlayerObjectHolder>();
        if (!playerHolder || !playerHolder.HasObjectInHand()) return;

        GameObject objectInHand = playerHolder.GetHeldObject();
        if (!IsValidHandObject(objectInHand)) return;

        loadedObject = objectInHand;
        var objTransform = objectInHand.transform;

        ClearPlayerHolder(playerHolder);

        Transform parentSocket = launchSocket ? launchSocket : rotatingArm;
        objTransform.SetParent(parentSocket, true);
        objTransform.localPosition = Vector3.zero;
        objTransform.localRotation = Quaternion.identity;

        isReady = false;
        if (currentOperation != null)
            StopCoroutine(currentOperation);
        currentOperation = StartCoroutine(LaunchSequence());

        // Notificar que la catapulta fue usada (para tutoriales)
        OnCatapultUsed?.Invoke(this);
    }

    private IEnumerator LaunchSequence()
    {
        // Calcular duración total de la secuencia para la barra de UI
        float highRotationDuration = CalculateRotationDuration(lowAngle, highAngle, launchRotationSpeed);
        float lowRotationDuration = CalculateRotationDuration(highAngle, lowAngle, reloadRotationSpeed);
        float totalDuration = highRotationDuration + lowRotationDuration;

        // Iniciar la barra de recarga
        StartReloadUI(totalDuration);

        yield return StartCoroutine(RotateToHighAngle());

        if (loadedObject && targetPoint)
        {
            var hitable = loadedObject.GetComponent<IHitable>();
            var targetT = loadedObject.transform;
            Vector3 destino = targetPoint.position;

            targetT.SetParent(null, true);
            hitable?.OnLaunched(destino);

            var routine = StartCoroutine(LaunchRoutine(targetT, destino));
            activeLaunches[targetT] = routine;

            loadedObject = null;
        }

        yield return StartCoroutine(RotateToLowAngle());

        isReady = true;
        currentOperation = null;
    }

    private void ClearPlayerHolder(PlayerObjectHolder holder)
    {
        var heldObjectField = typeof(PlayerObjectHolder).GetField("heldObject",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

        if (heldObjectField != null)
            heldObjectField.SetValue(holder, null);

        var disabledCollidersField = typeof(PlayerObjectHolder).GetField("heldDisabledColliders",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

        if (disabledCollidersField != null)
        {
            var list = disabledCollidersField.GetValue(holder) as System.Collections.IList;
            list?.Clear();
        }

        var rigidbodyField = typeof(PlayerObjectHolder).GetField("heldRigidbody",
            System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

        if (rigidbodyField != null)
            rigidbodyField.SetValue(holder, null);
    }

    private bool IsValidHandObject(GameObject obj)
    {
        if (!obj) return false;

        if (obj.GetComponent<IHitable>() != null) return true;
        if (obj.GetComponent<PaloIgnifugo>() != null) return true;
        if (obj.GetComponent<MaterialTipo1>() != null) return true;
        //if (obj.CompareTag("Item") || obj.CompareTag("Projectile")) return true;

        return false;
    }

    private void Awake()
    {
        if (!launchPoint) launchPoint = transform;
        if (!rotatingArm) rotatingArm = transform;
        if (!launchSocket) launchSocket = rotatingArm;

        // La barra de recarga permanece visible desde el inicio
        if (reloadImage)
        {
            reloadImage.gameObject.SetActive(true);
            reloadImage.fillAmount = 1f; // Comienza llena (catapulta lista)
        }
    }

    private void OnValidate()
    {
        if (!launchPoint) launchPoint = transform;
        if (!rotatingArm) rotatingArm = transform;
        if (!launchSocket) launchSocket = rotatingArm;
    }

    private void Start()
    {
        if (rotatingArm)
        {
            rotatingArm.localRotation = Quaternion.Euler(0f, 0f, lowAngle);
        }
        isReady = true;
    }

    public void SetTargetPoint(Transform target)
    {
        targetPoint = target;
    }

    private IEnumerator RotateToHighAngle()
    {
        if (!rotatingArm) yield break;

        float startAngle = rotatingArm.localEulerAngles.z;
        float targetAngle = highAngle;

        // Normalizar ángulos al rango -180 a 180
        if (startAngle > 180f) startAngle -= 360f;
        if (targetAngle > 180f) targetAngle -= 360f;

        // Calcular la diferencia y elegir el camino más corto
        float diff = targetAngle - startAngle;
        if (diff > 180f) diff -= 360f;
        if (diff < -180f) diff += 360f;

        float actualTarget = startAngle + diff;

        float duration = Mathf.Abs(diff) / launchRotationSpeed;

        float t = 0f;
        while (t < duration)
        {
            t += Time.deltaTime;
            float progress = t / duration;
            float currentAngle = Mathf.Lerp(startAngle, actualTarget, progress);
            rotatingArm.localRotation = Quaternion.Euler(0f, 0f, currentAngle);
            yield return null;
        }

        rotatingArm.localRotation = Quaternion.Euler(0f, 0f, targetAngle);
    }

    private IEnumerator RotateToLowAngle()
    {
        if (!rotatingArm) yield break;

        float startAngle = rotatingArm.localEulerAngles.z;
        float targetAngle = lowAngle;

        // Normalizar ángulos al rango -180 a 180
        if (startAngle > 180f) startAngle -= 360f;
        if (targetAngle > 180f) targetAngle -= 360f;

        // Calcular la diferencia y elegir el camino más corto
        float diff = targetAngle - startAngle;
        if (diff > 180f) diff -= 360f;
        if (diff < -180f) diff += 360f;

        float actualTarget = startAngle + diff;

        float duration = Mathf.Abs(diff) / reloadRotationSpeed;

        float t = 0f;
        while (t < duration)
        {
            t += Time.deltaTime;
            float progress = t / duration;
            float currentAngle = Mathf.Lerp(startAngle, actualTarget, progress);
            rotatingArm.localRotation = Quaternion.Euler(0f, 0f, currentAngle);
            yield return null;
        }

        rotatingArm.localRotation = Quaternion.Euler(0f, 0f, targetAngle);
    }

    private IEnumerator LaunchRoutine(Transform target, Vector3 destino)
    {
        if (!target) yield break;

        Vector3 start = launchPoint ? launchPoint.position : target.position;
        Vector3 startXZ = new Vector3(start.x, 0f, start.z);
        Vector3 endXZ = new Vector3(destino.x, 0f, destino.z);
        Vector3 flat = endXZ - startXZ;
        float distance = flat.magnitude;

        if (distance < minLaunchDistance)
        {
            target.position = destino;
            activeLaunches.Remove(target);
            yield break;
        }

        Vector3 dir = flat / Mathf.Max(distance, 0.0001f);
        float angleRad = launchAngleDeg * Mathf.Deg2Rad;
        float v = Mathf.Max(0.01f, launchSpeed);
        float g = Mathf.Max(0.01f, launchGravity);
        float sinAngle = Mathf.Sin(angleRad);
        float cosAngle = Mathf.Cos(angleRad);

        float a = -0.5f * g;
        float b = v * sinAngle;
        float c = start.y - destino.y;

        float discriminant = b * b - 4f * a * c;
        float totalTime;

        if (discriminant >= 0f)
        {
            float t1 = (-b + Mathf.Sqrt(discriminant)) / (2f * a);
            float t2 = (-b - Mathf.Sqrt(discriminant)) / (2f * a);
            totalTime = Mathf.Max(t1, t2);
        }
        else
        {
            totalTime = distance / (v * cosAngle);
        }

        totalTime = Mathf.Max(0.5f, totalTime);

        Rigidbody trb = target.GetComponent<Rigidbody>();
        bool hadRB = trb != null;
        bool prevKinematic = false;
        if (hadRB && kinematicDuringLaunch)
        {
            prevKinematic = trb.isKinematic;
            trb.isKinematic = true;
        }

        float t = 0f;
        while (t < totalTime && target != null)
        {
            t += Time.deltaTime;
            float progress = Mathf.Min(t / totalTime, 1f);

            Vector3 horizontalPos = Vector3.Lerp(start, destino, progress);
            float currentHeight = start.y + (v * sinAngle * t) - (0.5f * g * t * t);
            Vector3 currentPos = new Vector3(horizontalPos.x, currentHeight, horizontalPos.z);
            target.position = currentPos;

            yield return null;
        }

        if (target != null)
            target.position = destino;

        if (hadRB && kinematicDuringLaunch && trb != null)
            trb.isKinematic = prevKinematic;

        if (target != null)
            activeLaunches.Remove(target);
    }

    public bool IsReady() => isReady;
    public bool HasLoadedObject() => loadedObject != null;

    // Calcula la duración de una rotación dado el ángulo inicial, final y velocidad
    private float CalculateRotationDuration(float startAngle, float targetAngle, float rotationSpeed)
    {
        // Normalizar ángulos al rango -180 a 180
        if (startAngle > 180f) startAngle -= 360f;
        if (targetAngle > 180f) targetAngle -= 360f;

        // Calcular la diferencia y elegir el camino más corto
        float diff = targetAngle - startAngle;
        if (diff > 180f) diff -= 360f;
        if (diff < -180f) diff += 360f;

        return Mathf.Abs(diff) / Mathf.Max(0.1f, rotationSpeed);
    }

    // Inicia la UI de recarga con una duración total (segundos). Reemplaza cualquier UI en curso.
    private void StartReloadUI(float totalDuration)
    {
        if (reloadImage == null || totalDuration <= 0f) return;

        if (reloadUIUpdateCoroutine != null)
        {
            StopCoroutine(reloadUIUpdateCoroutine);
            reloadUIUpdateCoroutine = null;
        }

        reloadUIUpdateCoroutine = StartCoroutine(UpdateReloadBar(totalDuration));
    }

    private IEnumerator UpdateReloadBar(float totalDuration)
    {
        if (reloadImage == null) yield break;

        reloadImage.gameObject.SetActive(true);
        reloadImage.fillAmount = 0f;

        float elapsed = 0f;
        while (elapsed < totalDuration)
        {
            elapsed += Time.deltaTime;
            reloadImage.fillAmount = Mathf.Clamp01(elapsed / totalDuration);
            yield return null;
        }

        reloadImage.fillAmount = 1f;
        // La barra permanece visible y llena

        reloadUIUpdateCoroutine = null;
    }

    private void StopAndHideReloadUI()
    {
        if (reloadUIUpdateCoroutine != null)
        {
            StopCoroutine(reloadUIUpdateCoroutine);
            reloadUIUpdateCoroutine = null;
        }

        if (reloadImage)
        {
            reloadImage.fillAmount = 1f;
            // La barra permanece visible
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        if (launchPoint && targetPoint)
        {
            Gizmos.color = Color.red;
            Gizmos.DrawLine(launchPoint.position, targetPoint.position);
            Gizmos.DrawWireSphere(targetPoint.position, 0.5f);
        }

        if (rotatingArm)
        {
            Gizmos.color = Color.blue;
            Gizmos.DrawWireSphere(rotatingArm.position, 0.2f);

            Vector3 lowDir = Quaternion.Euler(0f, 0f, lowAngle) * Vector3.right;
            Gizmos.DrawLine(rotatingArm.position, rotatingArm.position + lowDir * 1f);

            Gizmos.color = Color.cyan;
            Vector3 highDir = Quaternion.Euler(0f, 0f, highAngle) * Vector3.right;
            Gizmos.DrawLine(rotatingArm.position, rotatingArm.position + highDir * 1f);
        }

        if (launchSocket)
        {
            Gizmos.color = Color.yellow;
            Gizmos.DrawWireCube(launchSocket.position, Vector3.one * 0.2f);
        }
    }
#endif
}
